const BREEDER_XP_DISCOUNT = 0.08;
const xpForBreederLevel = level => Math.max(1, Math.round(xpForLevel(level) * BREEDER_XP_DISCOUNT));
// ブリーダーレベルに意図した上限は無い。以前は200回で打ち切っていたため、
