  Easy: 2,
  Normal: 3,
  Hard: 4,
  Expert: 5,
  Master: 6,
  GrandMaster: 8,
  Hell: 10,
  Legend: 12,
  EXTREME: 15,
  NIGHTMARE: 20,
  CHAOS: 25,
  ULTIMATE: 30,
  INFINITY: 40
