// ---- 起動ローディングのゲージ ----
// 進み具合そのものは index.html の __mhBoot が持っている。静的なローディング画面と
// Reactのブート画面で同じ値を使うため、React側は数えなおさずここから読むだけにする。
// __mhBoot が無い環境(検証用に compiled.js だけを読み込む道具など)でも落ちないよう、
// そのときは「読み込み済み」として扱う。
const bootLoadRatio = () => {
  try {
    return window.__mhBoot ? window.__mhBoot.ratio() : 1;
  } catch (e) {
    return 1;
  }
};
const bootProgressNow = label => ({
  done: Math.round(bootLoadRatio() * 1000),
  total: 1000,
  label
});
const bootLoadDone = name => {
  try {
    if (window.__mhBoot) window.__mhBoot.done(name);
  } catch (e) {}
};
// 数え漏れが残っていてもゲージの右端まで伸ばす(終わったのに98%で止まって見えないように)
const bootLoadFinish = () => {
  try {
    if (window.__mhBoot) window.__mhBoot.finish();
  } catch (e) {}
};
const bootLoadWatch = fn => {
  try {
    return window.__mhBoot ? window.__mhBoot.watch(fn) : null;
  } catch (e) {
    return null;
  }
};

