      if (loginGrant.granted || compensationGrant.granted) {
        await storeSet('mh_gifts', compensationGrant.gifts, false);
      }
      if (loginGrant.granted) setLoginBonusPopup({
        day: loginGrant.day,
        rewards: loginGrant.gift.rewards
      });
      // ログインボーナスでptとして配ってしまったぶんを、経験値へ付け替える(一度きり)。
      // 経験値が増えてレベルが上がったぶんのポイントもここで配る
      const ptFixDone = await storeGet(LOGIN_PT_TO_XP_KEY, false, false);
      if (ptFixDone !== true) {
        const fixed = applyLoginPointFix(savedPoints, savedXp, compensationGrant.gifts);
        if (fixed.changed) {
          const gainedLevels = Math.max(0, levelInfo(fixed.xp).level - levelInfo(savedXp).level);
          savedPoints = fixed.points + gainedLevels;
          await storeSet('mh_breeder_xp', fixed.xp, false);
          setBreederXp(fixed.xp);
          await storeSet('mh_breeder_points', savedPoints, false);
          setBreederPoints(savedPoints);
          await storeSet('mh_breeder_points_granted', Math.max(0, levelInfo(fixed.xp).level - 1), false);
        }
        await storeSet(LOGIN_PT_TO_XP_KEY, true, false);
      }
      let missionState = normalizeMissions(await storeGet('mh_missions', null, false));
      const loginDay = missionDailyPeriod();
      missionState.daily.login = 1;
      if (!missionState.weeklyLoginDays.includes(loginDay)) missionState.weeklyLoginDays.push(loginDay);
      if (!missionState.monthlyLoginDays.includes(loginDay)) missionState.monthlyLoginDays.push(loginDay);
      missionState = reconcileMonthlyMissionCompletions(missionState);
      await storeSet('mh_missions', missionState, false);
      setMissions(missionState);
      const savedUnlockedMonsters = await storeGet('mh_unlocked_monsters', STARTER_MONSTER_IDS, false);
      setUnlockedMonsterIds(savedUnlockedMonsters);
      const availableBaseIds = Object.values(ALL_PLAYER_MONSTERS).map(mon => mon.id).filter(id => savedUnlockedMonsters.includes(id));
      setLastProParty(normalizeProLastParty(await storeGet(PRO_LAST_PARTY_KEY, null, false), availableBaseIds));
      const savedMonsterRoster = await storeGet('mh_monster_roster', savedUnlockedMonsters, false);
      const partySetsMigrated = await storeGet(MONSTER_PARTY_SETS_MIGRATED_KEY, false, false);
      const savedPartySets = partySetsMigrated === true ? await storeGet(MONSTER_PARTY_SETS_KEY, null, false) : null;
      const normalizedPartySets = normalizeMonsterPartySets(savedPartySets, savedMonsterRoster);
      if (partySetsMigrated !== true) {
        await storeSet(MONSTER_PARTY_SETS_KEY, normalizedPartySets, false);
        await storeSet(MONSTER_PARTY_SETS_MIGRATED_KEY, true, false);
      }
      setMonsterPartySets(normalizedPartySets);
      setEditingPartySetIndex(normalizedPartySets.activeIndex);
      const activeMonsterRoster = normalizedPartySets.rosters[normalizedPartySets.activeIndex];
      setMonsterRosterIds(activeMonsterRoster);
      const savedAutoSettings = normalizeAutoSettings(await storeGet(AUTO_SETTINGS_KEY, DEFAULT_AUTO_SETTINGS, false), activeMonsterRoster);
      setAutoSettings(savedAutoSettings);
      setDraftAutoSettings(savedAutoSettings);
      const savedUnlockedTeachings = await storeGet('mh_unlocked_teachings', STARTER_TEACHING_IDS, false);
      setUnlockedTeachingIds(savedUnlockedTeachings);
      // 保存が無い人の既定値を「解放済み全部」にしていたため、カードを買って解放が
      // 7枚以上になると編成もその枚数になり、バトルの手札が溢れていた。
      // 読むときは必ず正規化を通し、常にちょうど TEACHING_ROSTER_SIZE 枚にする。
      // 保存そのものは書き換えない(次に「決定」を押したときに正しい値で上書きされる)。
      const savedTeachingRoster = normalizeTeachingRoster(await storeGet('mh_teaching_roster', null, false), savedUnlockedTeachings);
      setTeachingRosterIds(savedTeachingRoster);
      const scores = {};
      const attempts = {};
      const clears = {};
      const reachedWaves = {};
      // クイックモードはチャレンジと別のキーへ保存しているので、まとめて読み込む
      const quickScores = {};
      const quickClears = {};
      const quickWaves = {};
      // プロモードもさらに別のキー(mh_pro_*)。まだ遊んだことがなければ既定値の0で埋まる
      const proScores = {};
      const proClears = {};
      const proWaves = {};
