        monEmoji: m.emoji,
        imgUrl: m.imgUrl,
        baseId: m.id,
        colors: m.colors,
        subLabel: `HP:${bHp}→${nMaxHp}  ちから:${bAtk}→${nAtk}\n丈夫さ:${bDef}→${nDef}  ガッツ:${bGuts}→${nMaxGuts}${aptLabel ? `\n間合い適性:${aptLabel}` : ''}`
